import diagrams as d

def table(headers, *rows, caption=None):
    h=''.join(f'<th>{x}</th>' for x in headers)
    r=''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)
    cap=f'<div class="caption">{caption}</div>' if caption else ''
    return f'<table class="visual-table"><thead><tr>{h}</tr></thead><tbody>{r}</tbody></table>{cap}'

def E(id,concept,subtopic,thinking,tier,prompt,answer,reasoning,visual=None,kind=(),source=None,atl=(),multiple=False,space='lines'):
    return dict(id=id,concept=concept,subtopic=subtopic,thinking=thinking,tier=tier,prompt=prompt,answer=answer,reasoning=reasoning,visual=visual,visual_kind=list(kind),source_id=source,atl=list(atl),multiple=multiple,space=space)

